            if subprocess.run(["git", "-C", str(t), *c], capture_output=True).returncode:
                return None
    return t

def binds(init: Path, name: str) -> bool:
    try: tree = ast.parse(init.read_text(errors="replace"))
    except Exception: return True
    for n in ast.walk(tree):  # top-level incl. if/try blocks
        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)) and n.name == name: return True
        if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Store) and n.id == name: return True
        if isinstance(n, (ast.Import, ast.ImportFrom)):
            for a in n.names:
                if (a.asname or a.name.split(".")[0]) == name: return True
    return False

